<?php

namespace App\Http\Controllers;

use App\Support\AuthStore;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Facades\Validator;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;

/**
 * Authenticated media uploads for course authors.
 *
 * Storage: the public disk (`storage/app/public/media/<kind>/…`), served at
 * `APP_URL/storage`. Bytes are indexed in `media_assets`, a service-role-only
 * table; the client receives the URL and stores it on a course/lesson row.
 *
 * File names are generated by Laravel's `store()` (random hashed name), so the
 * client-supplied name is never used as a path. Size and type are enforced
 * against a per-kind allow-list, and the server-detected MIME is what gets
 * recorded.
 */
class MediaController extends Controller
{
    /**
     * @var array<string, array{mimes: array<int, string>, max: int, extensions: array<int, string>}>
     */
    private const KINDS = [
        'image' => [
            'mimes' => ['jpg', 'jpeg', 'png', 'webp'],
            'extensions' => [],
            'max' => 5120,
        ],
        'caption' => [
            'mimes' => [],
            'extensions' => ['vtt', 'srt'],
            'max' => 2048,
        ],
        'audio' => [
            'mimes' => ['mp3', 'm4a', 'wav', 'ogg'],
            'extensions' => [],
            'max' => 51200,
        ],
        'video' => [
            'mimes' => ['mp4', 'webm'],
            'extensions' => [],
            'max' => 204800,
        ],
    ];

    private const AUTHOR_ROLES = ['Partner', 'Instructor', 'Administrator'];

    public function store(Request $request)
    {
        $user = $request->attributes->get('auth_user');
        $role = (string) ($user->type ?? '');

        if (! in_array($role, self::AUTHOR_ROLES, true)) {
            return response()->json(['message' => 'Only course authors can upload media.'], 403);
        }

        $kind = (string) $request->input('kind', '');

        if (! array_key_exists($kind, self::KINDS)) {
            return response()->json(['message' => 'Choose a valid media type.'], 422);
        }

        $rules = self::KINDS[$kind];
        $typeRule = $rules['extensions'] === []
            ? 'mimes:'.implode(',', $rules['mimes'])
            : 'extensions:'.implode(',', $rules['extensions']);

        $validator = Validator::make($request->all(), [
            'kind' => ['required', Rule::in(array_keys(self::KINDS))],
            'file' => ['required', 'file', 'max:'.$rules['max'], $typeRule],
        ]);

        if ($validator->fails()) {
            return response()->json([
                'message' => $validator->errors()->first(),
                'errors' => $validator->errors(),
            ], 422);
        }

        $file = $request->file('file');
        $partnerId = null;

        if ($role === 'Partner') {
            $partnerId = AuthStore::service(
                fn () => DB::table('users')->where('id', $user->id)->value('partner_id'),
            );
        }

        $path = $file->store('media/'.$kind, 'public');
        $url = Storage::disk('public')->url($path);

        $asset = [
            'owner_profile_id' => $user->id,
            'partner_id' => $partnerId,
            'provider' => 'local',
            'kind' => $kind,
            'storage_key' => $path,
            'url' => $url,
            'mime' => (string) $file->getMimeType(),
            'bytes' => (int) $file->getSize(),
            'checksum' => hash_file('sha256', (string) $file->getRealPath()),
            'original_name' => Str::limit(basename((string) $file->getClientOriginalName()), 255, ''),
            'status' => 'ready',
            'created_at' => now(),
            'updated_at' => now(),
        ];

        $id = AuthStore::service(fn () => DB::table('media_assets')->insertGetId($asset));

        return response()->json([
            'data' => [
                'id' => $id,
                'kind' => $kind,
                'url' => $url,
                'mime' => $asset['mime'],
                'bytes' => $asset['bytes'],
                'checksum' => $asset['checksum'],
            ],
        ], 201);
    }
}
